<?php
require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['especialista'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT r.*,s.id_solicitud,s.marca,s.modelo,s.problema_reportado,s.descripcion,u.nombre AS cliente FROM reparaciones r JOIN solicitudes s ON s.id_solicitud=r.id_solicitud JOIN usuarios u ON u.id_usuario=s.id_cliente WHERE r.id_reparacion=? AND r.id_especialista=?');$q->execute([$id,$_SESSION['usuario']['id_usuario']]);$reparacion=$q->fetch();if(!$reparacion){establecer_mensaje('error','Reparación no encontrada o no asignada a ti.');redirigir('mis_reparaciones.php');}$q=$pdo->prepare('SELECT h.*,u.nombre FROM historial_reparacion h JOIN usuarios u ON u.id_usuario=h.usuario_actualiza WHERE h.id_reparacion=? ORDER BY h.fecha_actualizacion');$q->execute([$id]);$historial=$q->fetchAll();$titulo_pagina='Detalle de reparación';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
?><div class="cabecera-panel"><div><span class="etiqueta">REPARACIÓN #<?= $id ?></span><h1><?= escapar($reparacion['marca'].' '.$reparacion['modelo']) ?></h1><p>Cliente: <?= escapar($reparacion['cliente']) ?> · Falla: <?= escapar($reparacion['problema_reportado']) ?></p></div><a class="boton" href="actualizar_reparacion.php?id=<?= $id ?>">Actualizar estado</a></div><div class="barra-progreso"><?php $estados=['Pendiente','Diagnóstico','En reparación','En pruebas','Terminada'];$indice=array_search($reparacion['estado'],$estados);foreach($estados as $i=>$estado): ?><div class="paso-progreso <?= $i<=$indice?'activo':'' ?>"><i><?= $i+1 ?></i><span><?= $estado ?></span></div><?php endforeach; ?></div><div class="rejilla-dos"><section class="tarjeta"><h3>Ficha técnica</h3><div class="fila-detalle"><span>Descripción del cliente</span><strong><?= escapar($reparacion['descripcion']) ?></strong></div><div class="fila-detalle"><span>Diagnóstico</span><strong><?= escapar($reparacion['diagnostico']?:'Pendiente') ?></strong></div><div class="fila-detalle"><span>Trabajo realizado</span><strong><?= escapar($reparacion['trabajo_realizado']?:'Pendiente') ?></strong></div><div class="fila-detalle"><span>Piezas utilizadas</span><strong><?= escapar($reparacion['piezas_utilizadas']?:'Ninguna registrada') ?></strong></div><div class="fila-detalle"><span>Observaciones</span><strong><?= escapar($reparacion['observaciones']?:'—') ?></strong></div></section><section class="tarjeta"><h3>Historial de cambios</h3><?php foreach($historial as $h): ?><div class="fila-detalle"><div><strong><?= escapar($h['estado_nuevo']) ?></strong><br><small><?= escapar($h['comentario']) ?></small></div><small><?= date('d/m H:i',strtotime($h['fecha_actualizacion'])) ?></small></div><?php endforeach; ?></section></div><?php require_once __DIR__.'/../includes/pie.php'; ?>



